from __future__ import annotations

import argparse
import sys
from pathlib import Path

from omv_mcp.tools.registry import ALL_PLUGIN_PACKAGES, Tier, iter_tools

TIER_NAME = {Tier.READONLY: "readonly", Tier.OPERATOR: "operator", Tier.ADMIN: "admin"}


def render() -> str:
    specs = sorted(
        iter_tools(frozenset(ALL_PLUGIN_PACKAGES.values())),
        key=lambda spec: (spec.tier, spec.name),
    )
    lines = [
        "# Tool reference",
        "",
        "Generated by `scripts/gen_tools_doc.py`; do not edit by hand.",
        "",
        "| Tool | Tier | RPCs | Description | Side effects |",
        "|---|---|---|---|---|",
    ]
    for spec in specs:
        effects = []
        if spec.annotations.destructive_hint:
            effects.append("destructive")
        if spec.annotations.idempotent_hint is False:
            effects.append("not idempotent")
        if spec.tier is not Tier.READONLY:
            effects.append("plan + confirm; may mark modules dirty")
        lines.append(
            f"| `{spec.name}` | {TIER_NAME[spec.tier]} | "
            f"{', '.join(f'`{rpc}`' for rpc in spec.rpcs)} | "
            f"{spec.description} | {'; '.join(effects) or 'none'} |"
        )
    lines.append("")
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = Path("docs/tools.md")
    text = render()
    if args.check:
        if not path.exists() or path.read_text() != text:
            print("docs/tools.md is out of date", file=sys.stderr)
            raise SystemExit(1)
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)


if __name__ == "__main__":
    main()
